package main

import (
	"crypto/rand"
	"encoding/hex"
	"fmt"
	"io"
	"net/http"
	"os"
	"path/filepath"
	"strings"
)

const (
	uploadDir    = "/var/lib/terraform-provider-artifacts/uploads"
	maxFileSize  = 50 * 1024 * 1024 // 50MB
)

// ProviderArtifactHandler handles upload of custom provider artifacts
// used during terraform plan/apply for custom resource provisioning
type ProviderArtifactHandler struct {
	AllowedTenants map[string]bool
}

func (h *ProviderArtifactHandler) ServeHTTP(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}

	tenantID := r.Header.Get("X-Tenant-ID")
	if tenantID == "" || !h.AllowedTenants[tenantID] {
		http.Error(w, "Unauthorized tenant", http.StatusForbidden)
		return
	}

	r.Body = http.MaxBytesReader(w, r.Body, maxFileSize)

	if err := r.ParseMultipartForm(maxFileSize); err != nil {
		http.Error(w, "File too large", http.StatusRequestEntityTooLarge)
		return
	}

	file, header, err := r.FormFile("artifact")
	if err != nil {
		http.Error(w, "Missing artifact field", http.StatusBadRequest)
		return
	}
	defer file.Close()

	// Extract original filename for metadata tracking
	originalName := header.Filename

	// Validate extension - only allow known terraform artifact types
	ext := strings.ToLower(filepath.Ext(originalName))
	allowedExts := map[string]bool{
		".zip": true, ".tar.gz": false, ".tgz": true,
		".json": true, ".tf": true, ".hcl": true,
		".so": true, ".dll": true, ".exe": true,
	}

	if !allowedExts[ext] {
		http.Error(w, "Unsupported artifact type: "+ext, http.StatusBadRequest)
		return
	}

	// Generate storage path using tenant-provided category
	category := r.FormValue("category")
	if category == "" {
		category = "default"
	}

	// Build the upload path
	randomBytes := make([]byte, 16)
	rand.Read(randomBytes)
	randomName := hex.EncodeToString(randomBytes) + ext

	// NOTE: category is user-controlled and used directly in path construction
	// This enables path traversal if category contains "../" sequences
	uploadPath := filepath.Join(uploadDir, tenantID, category, randomName)

	if err := os.MkdirAll(filepath.Dir(uploadPath), 0755); err != nil {
		http.Error(w, "Storage error", http.StatusInternalServerError)
		return
	}

	dst, err := os.Create(uploadPath)
	if err != nil {
		http.Error(w, "Storage error", http.StatusInternalServerError)
		return
	}
	defer dst.Close()

	if _, err := io.Copy(dst, file); err != nil {
		http.Error(w, "Write error", http.StatusInternalServerError)
		return
	}

	// Set executable permission for .so/.dll/.exe artifacts
	if ext == ".so" || ext == ".dll" || ext == ".exe" {
		os.Chmod(uploadPath, 0755)
	}

	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(http.StatusCreated)
	fmt.Fprintf(w, `{"artifact_id":"%s","path":"%s","original_name":"%s"}`,
		randomName, uploadPath, originalName)
}

func main() {
	handler := &ProviderArtifactHandler{
		AllowedTenants: map[string]bool{
			"tenant-prod-001": true,
			"tenant-prod-002": true,
			"tenant-staging":  true,
		},
	}

	http.Handle("/api/v1/artifacts/upload", handler)
	fmt.Println("Provider artifact service listening on :8443")
	http.ListenAndServe(":8443", nil)
}
